function confirmedContact({ record, email, expectedId = "", stage = false }) {
  const id = record?.id;
  const returnedEmail = record?.properties?.email;
  if (
    typeof id !== "string" ||
    !/^[1-9][0-9]*$/.test(id) ||
    record.archived === true ||
    (expectedId && expectedId !== "0" && id !== expectedId) ||
    (stage && record.properties?.lifecyclestage !== "opportunity") ||
    ((!stage || returnedEmail != null) &&
      (typeof returnedEmail !== "string" || returnedEmail.toLowerCase() !== email.toLowerCase()))
  ) {
    throw new Error("HubSpot did not confirm the matching contact");
  }
  return id;
}
function selectContact({ records, email, paging }) {
  if (!Array.isArray(records) || records.length > 1 || paging?.nextAfter || paging?.next?.after) {
    throw new Error("HubSpot did not confirm a unique email match");
  }
  return records.length
    ? { existing: true, recordId: confirmedContact({ record: records[0], email }) }
    : { existing: false, recordId: "0" };
}
export default ({ result, email }) =>
  selectContact({
    records: result?.results ?? result?.records ?? result?.objects ?? result?.items,
    paging: result?.paging,
    email,
  });

