export default async ({ key, interested, recordId, messageId }, context) => {
  if (interested && (typeof messageId !== "string" || !messageId))
    throw new Error("Gmail did not confirm a sent message");
  await context.state.set(key, {
    status: interested ? "sent" : "saved",
    recordId,
    ...(interested ? { messageId } : {}),
  });
  return {};
};
